        submitTest(batchKey, testReq("TK-1", "t1", "PASS", "i"), null, null, 201);
        // 同一检验项换 testKey 重复提交 → 409
        submitTest(batchKey, testReq("TK-2", "t1", "PASS", "i"), null, null, 409);
        submitTest(batchKey, testReq("TK-3", "t2", "PASS", "i"), null, null, 201);

