package com.example.starter.batch.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;

import java.time.Instant;
import java.util.List;

/**
 * 创建批次请求。producedAt 为 ISO-8601 UTC 时间；requiredTests 为 1～5 个必做检验项。
 * allergens 为过敏原集合，可空（视为空集合）；服务端逐项 trim、去重并按字典序稳定排序后持久化。
 * cleanGeneration 为生产线清洁代次，可空（默认 1），必须为正整数。
 */
public record CreateBatchRequest(
        @NotBlank(message = "commandKey 不能为空") String commandKey,
        @NotBlank(message = "batchKey 不能为空") String batchKey,
        @NotBlank(message = "productCode 不能为空") String productCode,
        @NotBlank(message = "batchNo 不能为空") String batchNo,
        @NotNull(message = "producedAt 不能为空") Instant producedAt,
        @NotNull(message = "requiredTests 不能为空")
        @Size(min = 1, max = 5, message = "requiredTests 必须包含 1～5 个检验项")
        List<@NotBlank(message = "检验项不能为空") String> requiredTests,
        @Size(max = 20, message = "allergens 最多包含 20 个过敏原")
        List<@NotBlank(message = "过敏原不能为空") String> allergens,
        @Positive(message = "cleanGeneration 必须为正整数") Integer cleanGeneration
) {
}

package com.example.starter.batch.dto;

import com.example.starter.batch.BatchStatus;

import java.time.Instant;
import java.util.List;

/**
 * 批次概要响应。producedAt/createdAt 为 UTC instant。
 * allergens 为规范化（去重、字典序稳定排序）后的过敏原集合，空集合表示无登记过敏原；
 * cleanGeneration 为批次当前生产线清洁代次（推进后随之变化）；
 * mergeBasis 仅合批子批非空，为该子批固化的合批依据，事后不随清洁推进改写。
 */
public record BatchResponse(
        String batchKey,
        String productCode,
        String batchNo,
        Instant producedAt,
        BatchStatus status,
        List<String> requiredTests,
        List<String> allergens,
        int cleanGeneration,
        MergeBasisResponse mergeBasis,
        Instant createdAt
) {
}

package com.example.starter.batch.dto;

import java.time.Instant;
import java.util.List;

/**
 * 合批子批冻结依据：固化的清洁代次、过敏原集合与各父批合批时快照。
 * 该依据在合批落定时写入，后续产线清洁推进或父批变化均不改写。
 */
public record MergeBasisResponse(
        int frozenCleanGeneration,
        List<String> frozenAllergens,
        List<MergeResponse.ParentBasis> parents,
        Instant mergedAt
) {
}

package com.example.starter.batch.dto;

import java.util.List;

/**
 * 批次完整历史明细：批次概要 + 全部检验结果 + 全部批准 + 召回记录（未召回时 recall 为 null）。
 * mergeBasis 仅合批子批非空（与批次概要中的冻结依据一致）；
 * mergedIntoChildKey 仅参与过合批的父批非空，指向其被并入的合批子批业务键。
 */
public record BatchHistoryResponse(
        BatchResponse batch,
        List<TestResultResponse> tests,
        List<ApprovalResponse> approvals,
        RecallResponse recall,
        MergeBasisResponse mergeBasis,
        String mergedIntoChildKey
) {
}

package com.example.starter.batch.dto;

import com.example.starter.batch.BatchStatus;

