    seen.add(batchKey);
    while (!queue.isEmpty()) {
        String current = queue.poll();
        for (BatchRepository.LineageRow edge : incoming.getOrDefault(current, List.of())) {
            String parent = edge.parentKey();
            if (recalled.contains(parent)) {
                return Optional.of(parent);
            }
            if (seen.add(parent)) {
                queue.add(parent);
            }
        }
    }
    return Optional.empty();
}

